import { InputMapping, OutputMapping } from "@/types/mapping";
import { ReadOnlyMappingsTable } from "@/components/shared/ReadOnlyMappingsTable";

interface ReadOnlyMappingsSectionProps {
  type: "input" | "output";
  mappings: (InputMapping | OutputMapping)[];
}

export function ReadOnlyMappingsSection({
  type,
  mappings,
}: ReadOnlyMappingsSectionProps) {
  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center">
        <h3 className="font-semibold">{type === "input" ? "Input" : "Output"} Mappings</h3>
        <div className="text-sm text-gray-500">
          {mappings.length} mapping{mappings.length !== 1 ? 's' : ''}
        </div>
      </div>

      <ReadOnlyMappingsTable
        type={type}
        mappings={mappings}
      />
    </div>
  );
} 