import { Button } from "@/components/ui/buttons/button";
import { MappingsSection } from "@/components/mapping/MappingsSection";
import { useExcelTemplate } from "@/hooks/useExcelTemplate";
import { useMappingForm } from "@/hooks/useMappingForm";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/layout";
import { TemplateHeader } from "@/components/mapping/TemplateHeader";
import { Alert, AlertDescription } from "@/components/ui/feedback/alert";
import { toast } from "react-toastify";
import { MappingTypeSelect } from "@/components/mapping/MappingTypeSelect";
import { generateNumericId } from "@/utils/idGenerator";
import { updateTemplate, createTemplate } from "@/services/templateService";
import { ValidationRule, createValidationRule, validateRules } from "@/utils/validation";
import { debugMetaSheet, showMetaSheet, hideMetaSheet } from "@/lib/excel/office";

const useTemplateValidation = (formState: ReturnType<typeof useMappingForm>) => {
  const {
    templateName,
    inputMappings,
    outputMappings,
    selectedMappingIds,
    setError,
    setMappingTypeError,
  } = formState;

  const validationRules: Record<string, ValidationRule> = {
    templateName: createValidationRule(
      () => Boolean(templateName?.trim()),
      "Template name is required",
      () => setError("templateName", "Template name is required")
    ),
    inputMappings: createValidationRule(
      () => inputMappings.length > 0,
      "At least one input mapping is required",
      () => setError("form", "At least one input mapping is required")
    ),
    outputMappings: createValidationRule(
      () => outputMappings.length > 0,
      "At least one output mapping is required",
      () => setError("form", "At least one output mapping is required")
    ),
    inputMappingValues: createValidationRule(
      () => {
        const invalidInputs = inputMappings.filter(mapping => !mapping.cell || !mapping.column?.trim());
        if (invalidInputs.length > 0) {
          invalidInputs.forEach(mapping => {
            if (!mapping.cell) {
              setError(`input_cell_${mapping.id}`, "Cell must be selected");
            }
            if (!mapping.column?.trim()) {
              setError(`input_name_${mapping.id}`, "Column name is required");
            }
          });
          return false;
        }
        return true;
      },
      "All input mappings must have both cell and column name",
      () => setError("form", "All input mappings must have both cell and column name")
    ),
    outputMappingValues: createValidationRule(
      () => {
        const invalidOutputs = outputMappings.filter(mapping => !mapping.cell || !mapping.name?.trim());
        if (invalidOutputs.length > 0) {
          invalidOutputs.forEach(mapping => {
            if (!mapping.cell) {
              setError(`output_cell_${mapping.id}`, "Cell must be selected");
            }
            if (!mapping.name?.trim()) {
              setError(`output_name_${mapping.id}`, "Name is required");
            }
          });
          return false;
        }
        return true;
      },
      "All output mappings must have both cell and name values",
      () => setError("form", "All output mappings must have both cell and name values")
    ),
    mappingType: createValidationRule(
      () => {
        if (inputMappings.length === 0) return true;
        if (!selectedMappingIds.length) {
          setMappingTypeError("Please select at least one mapping type");
          return false;
        }
        const selectedMapping = inputMappings.find(m => m.id === selectedMappingIds[0]);
        if (!selectedMapping?.column) {
          setMappingTypeError("Please enter a name for the selected mapping");
          return false;
        }
        return true;
      },
      "Invalid mapping type selection",
      () => setMappingTypeError("Invalid mapping type selection")
    ),
  };

  return { validateForm: () => validateRules(validationRules) && (setMappingTypeError(""), true) };
};

const useTemplateSubmission = (formState: ReturnType<typeof useMappingForm>) => {
  const {
    templateName,
    description,
    inputMappings,
    outputMappings,
    identityMappings,
    isEditMode,
    originalTemplate,
    resetForm,
  } = formState;

  const submitTemplate = async () => {
    const templateData = {
      name: templateName,
      description,
      inputMappings,
      outputMappings,
      identityMappings: identityMappings.map(identity => ({
        id: generateNumericId(),
        templateId: originalTemplate ? originalTemplate.id : "0",
        name: identity.name,
      })),
    };

    try {
      if (isEditMode && originalTemplate) {
        await updateTemplate(originalTemplate.id, {
          name: templateName,
          description,
          inputMappings,
          outputMappings,
          identityMappings: identityMappings.map(identity => ({
            id: generateNumericId(),
            templateId: originalTemplate.id,
            name: identity.name,
          })),
        });
      } else {
        await createTemplate(templateData);
      }

      resetForm();
      toast.success(`Template ${isEditMode ? "updated" : "saved"} successfully!`);
    } catch (error) {
      toast.error((error as Error).message || `Failed to ${isEditMode ? "update" : "save"} template`);
    }
  };

  return { submitTemplate };
};

export default function NewMappingForm() {
  const formState = useMappingForm();
  const { handleCellSelect } = useExcelTemplate();
  const { validateForm } = useTemplateValidation(formState);
  const { submitTemplate } = useTemplateSubmission(formState);

  const {
    templateName,
    setTemplateName,
    description,
    setDescription,
    inputMappings,
    addInputMapping,
    removeInputMapping,
    updateInputMapping,
    outputMappings,
    addOutputMapping,
    removeOutputMapping,
    updateOutputMapping,
    errors,
    setError,
    clearError,
    isSubmitting,
    selectedMappingIds,
    setSelectedMappingIds,
    mappingTypeError,
    setMappingTypeError,
    isEditMode,
  } = formState;

  const handleSelectCell = async (id: string, type: "input" | "output") => {
    const result = await handleCellSelect(type === "input");
    if (!result) return;

    const { cell, hasFormula } = result;

    if (hasFormula && type === "input") {
      setError(`${type}_cell_formula_${id}`, "Cannot use a formula cell as input");
      return;
    }

    clearError(`${type}_cell_formula_${id}`);
    if (type === "input") {
      updateInputMapping(id, "cell", cell);
    } else {
      updateOutputMapping(id, "cell", cell);
    }
  };

  const handleDebugMeta = async () => {
    try {
      const info = await debugMetaSheet();
      toast.info(info, { autoClose: 8000 });
    } catch (error) {
      toast.error(`Error checking meta sheet: ${error}`);
    }
  };

  const handleShowMeta = async () => {
    try {
      await showMetaSheet();
      toast.success("Meta sheet is now visible!");
    } catch (error) {
      toast.error(`Error showing meta sheet: ${error}`);
    }
  };

  const handleHideMeta = async () => {
    try {
      await hideMetaSheet();
      toast.success("Meta sheet is now hidden!");
    } catch (error) {
      toast.error(`Error hiding meta sheet: ${error}`);
    }
  };

  const allErrors = [
    errors.form,
    mappingTypeError,
    ...Object.entries(errors)
      .filter(([key]) =>
        (key.startsWith('input_') || key.startsWith('output_')) && key !== 'templateName')
      .map(([, value]) => value)
  ].filter(Boolean);

  return (
    <Card>
      <CardHeader>
        <CardTitle>{isEditMode ? "Edit Template" : "Create New Template"}</CardTitle>
      </CardHeader>
      <CardContent className="space-y-2">
        {allErrors.length > 0 && (
          <Alert variant="destructive">
            <AlertDescription>
              <ul className="list-disc pl-4">
                {allErrors.map((error, index) => (
                  <li key={index}>{error}</li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        <TemplateHeader
          templateName={templateName}
          setTemplateName={setTemplateName}
          description={description}
          setDescription={setDescription}
          errors={errors}
        />

        <MappingsSection
          type="input"
          mappings={inputMappings}
          errors={errors}
          onAdd={addInputMapping}
          onRemove={removeInputMapping}
          onSelectCell={(id) => handleSelectCell(id, "input")}
          onChange={updateInputMapping}
        />

        {inputMappings.length > 0 && (
          <MappingTypeSelect
            inputMappings={inputMappings}
            selectedMappingIds={selectedMappingIds}
            setSelectedMappingIds={setSelectedMappingIds}
            setMappingTypeError={setMappingTypeError}
          />
        )}

        <MappingsSection
          type="output"
          mappings={outputMappings}
          errors={errors}
          onAdd={addOutputMapping}
          onRemove={removeOutputMapping}
          onSelectCell={(id) => handleSelectCell(id, "output")}
          onChange={updateOutputMapping}
        />

        <div className="flex justify-end gap-2">
          <Button 
            variant="outline" 
            size="sm" 
            onClick={handleDebugMeta}
            className="text-xs"
          >
            Debug Meta
          </Button>
          <Button 
            variant="outline" 
            size="sm" 
            onClick={handleShowMeta}
            className="text-xs"
          >
            Show Meta
          </Button>
          <Button 
            variant="outline" 
            size="sm" 
            onClick={handleHideMeta}
            className="text-xs"
          >
            Hide Meta
          </Button>
          <Button variant="excel" onClick={() => validateForm() && submitTemplate()} disabled={isSubmitting}>
            {isSubmitting ? "Saving..." : isEditMode ? "Update Template" : "Save Template"}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}
