import { useState } from "react";
import { exportActiveWorkbookAsFile } from "@/lib/excel/office";
import { toast } from "react-toastify";

export const useActiveExcel = () => {
  const [isLoading, setIsLoading] = useState(false);

  const getActiveExcelFile = async (): Promise<{ file: File; workbookName: string } | null> => {
    setIsLoading(true);
    
    try {
      if (typeof Office === 'undefined' || typeof Excel === 'undefined') {
        toast.error("Excel API is not available. Make sure you are running in Excel.");
        return null;
      }

      // Get the name of the active workbook
      const workbookName = await Excel.run(async (context) => {
        const workbook = context.workbook;
        workbook.load('name');
        await context.sync();
        return workbook.name || 'Active Workbook';
      });

      const activeFile = await exportActiveWorkbookAsFile();
      
      if (!activeFile) {
        toast.error("Failed to get active Excel file");
        return null;
      }

      toast.success("Active Excel file loaded successfully!");
      return { file: activeFile, workbookName };
      
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast.error(`Error getting Excel file: ${errorMessage}`);
      return null;
    } finally {
      setIsLoading(false);
    }
  };

  return {
    getActiveExcelFile,
    isLoading
  };
}; 