import React from "react";

interface TableColumn<T> {
  key: string;
  title: string | React.ReactNode;
  className?: string;
  render?: (item: T) => React.ReactNode;
}

interface GenericTableProps<T> {
  columns: TableColumn<T>[];
  data: T[];
  className?: string;
  renderRow: (item: T, index?: number) => React.ReactNode;
  maxHeight?: string;
}

export function GenericTable<T>({ columns, data, className = "", renderRow, maxHeight = "400px" }: GenericTableProps<T>) {
  return (
    <div className={`bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden ${className}`}>
      <div className="overflow-auto" style={{ maxHeight }}>
        <table className="w-full table-fixed">
          <thead className="sticky top-0 z-10">
            <tr className="bg-gray-700 text-white">
              {columns.map((column) => (
                <th
                  key={column.key}
                  className={`px-2 py-2 text-xs font-semibold border-r border-gray-600 whitespace-nowrap ${column.className || ""}`}
                >
                  {typeof column.title === 'string' ? column.title : column.title}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {data.map((item, index) => renderRow(item, index))}
          </tbody>
        </table>
      </div>
      {data.length === 0 && (
        <div className="text-center py-8 text-gray-500">
          <p>No data available</p>
        </div>
      )}
    </div>
  );
}

export type { TableColumn, GenericTableProps }; 