export interface InputMapping {
  id: string;
  column: string;
  cell: string;
  forcedValue?: string | null;
  source?: "input_file" | "forced_input";
}

export interface OutputMapping {
  id: string;
  name: string;
  cell: string;
}

export interface IdentityMapping {
  id: string;
  templateId: string;
  name: string;
}

export interface Template {
  id: string;
  name: string;
  description: string;
  inputMappings: InputMapping[];
  outputMappings: OutputMapping[];
  identityMappings: IdentityMapping[];
  createdAt: string;
}

// Helper function for generating identityMappings
export const generateIdentityMappings = (
  template: Omit<Template, 'identityMappings'>,
  selectedIds: string[]
): IdentityMapping[] => {
  return selectedIds
    .map(selectedId => {
      const inputMapping = template.inputMappings.find(m => m.id === selectedId);
      if (!inputMapping) return null;
      
      return {
        id: `identity-${selectedId}`,
        templateId: template.id,
        name: inputMapping.column
      };
    })
    .filter((mapping): mapping is IdentityMapping => mapping !== null);
};

// Helper functions for working with identity mappings
export const getSelectedMappingIds = (template: Template): string[] => {
  return template.inputMappings
    .filter(inputMapping => 
      template.identityMappings.some(identity => identity.name === inputMapping.column)
    )
    .map(inputMapping => inputMapping.id);
};

export const isIdentityMapping = (template: Template, mappingId: string): boolean => {
  const inputMapping = template.inputMappings.find(m => m.id === mappingId);
  if (!inputMapping) return false;
  
  return template.identityMappings.some(identity => identity.name === inputMapping.column);
};

export const addIdentityMapping = (template: Template, mappingId: string): IdentityMapping[] => {
  const inputMapping = template.inputMappings.find(m => m.id === mappingId);
  if (!inputMapping) return template.identityMappings;
  
  const exists = template.identityMappings.some(identity => identity.name === inputMapping.column);
  if (exists) return template.identityMappings;
  
  const newIdentity: IdentityMapping = {
    id: `identity-${mappingId}`,
    templateId: template.id,
    name: inputMapping.column
  };
  
  return [...template.identityMappings, newIdentity];
};

export const removeIdentityMapping = (template: Template, mappingId: string): IdentityMapping[] => {
  const inputMapping = template.inputMappings.find(m => m.id === mappingId);
  if (!inputMapping) return template.identityMappings;
  
  return template.identityMappings.filter(identity => identity.name !== inputMapping.column);
}; 