import { Input } from "@/components/ui/forms";
import { Template } from "@/types/mapping";
import { FileText } from "lucide-react";

interface CsvOnlyUploaderProps {
  selectedTemplate: Template | null;
  csvPreview: string[][];
  csvFile: File | null;
  handleCsvChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
}

export const CsvOnlyUploader = ({
  selectedTemplate,
  csvPreview,
  csvFile,
  handleCsvChange,
}: CsvOnlyUploaderProps) => {
  const allForcedInputs = selectedTemplate?.inputMappings?.every(i => i.source === "forced_input") || false;
  const showCsvUploader = !allForcedInputs && Boolean(selectedTemplate?.inputMappings?.length);

  if (!showCsvUploader) return null;

  return (
    <div className="mb-6">
      <label className="block mb-1 text-base font-semibold">Upload CSV</label>
      <div className="border-2 border-dashed border-gray-300 rounded-xl p-4 text-center">
        <Input 
          type="file" 
          accept=".csv" 
          onChange={handleCsvChange} 
          className="hidden placeholder:text-gray-400" 
          id="csv-upload" 
        />
        <label 
          htmlFor="csv-upload" 
          className="cursor-pointer flex flex-col items-center hover:bg-gray-50 transition-colors duration-200 p-2 rounded-lg"
        >
          <FileText className="h-8 w-8 mb-2 text-green-600" />
          <div className="text-sm font-medium text-green-600">Choose CSV File</div>
          <div className="text-xs text-gray-500 mt-1">CSV format only</div>
        </label>
        {csvFile && (
          <div className="mt-3 p-2 bg-green-50 rounded-lg border border-green-200">
            <div className="text-sm text-green-700 font-medium">
              Selected: {csvFile.name}
            </div>
          </div>
        )}
      </div>
      
      {csvPreview.length > 0 && (
        <div className="bg-gray-50 border border-gray-200 rounded-xl p-4 text-xs mt-3">
          <div className="font-semibold mb-3 text-green-700 text-sm">Preview:</div>
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <tbody>
                {csvPreview.map((row, i) => (
                  <tr key={i} className={`${i === 0 ? 'bg-green-50 font-medium' : 'bg-white'}`}>
                    {row.map((cell, j) => (
                      <td key={j} className="border border-gray-200 p-1.5 whitespace-nowrap rounded-sm">
                        {cell || <span className="text-gray-300">(empty)</span>}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}; 