import { create } from 'zustand';
import { ExcelFileInfo } from '@/lib/excel/office';

interface ExcelFileState {
  currentFile: ExcelFileInfo | null;
  setCurrentFile: (file: ExcelFileInfo) => void;
  clearCurrentFile: () => void;
}

export const useExcelFileStore = create<ExcelFileState>((set) => ({
  currentFile: null,
  setCurrentFile: (file) => set({ currentFile: file }),
  clearCurrentFile: () => set({ currentFile: null }),
})); 