import { useState, useMemo, useCallback } from "react";

export function usePagination<T>(data: T[], initialPageSize: number = 50) {
  const [visibleCount, setVisibleCount] = useState(initialPageSize);

  const visibleData = useMemo(() => 
    data.slice(0, visibleCount), 
    [data, visibleCount]
  );

  const hasMore = useMemo(() => 
    visibleCount < data.length, 
    [visibleCount, data.length]
  );

  const remainingCount = useMemo(() => 
    Math.max(0, data.length - visibleCount), 
    [data.length, visibleCount]
  );

  const loadMore = useCallback(() => {
    if (hasMore) {
      setVisibleCount(prev => Math.min(prev + initialPageSize, data.length));
    }
  }, [hasMore, initialPageSize, data.length]);

  const reset = useCallback(() => {
    setVisibleCount(initialPageSize);
  }, [initialPageSize]);

  return {
    visibleData,
    visibleCount,
    hasMore,
    remainingCount,
    loadMore,
    reset
  };
} 