import { useState, useEffect, useRef } from "react";

interface UseExcelCellPickerProps {
  isOpen: boolean;
  isColumnPicker: boolean;
  initialCell: string;
}

export function useExcelCellPicker({ isOpen, isColumnPicker, initialCell }: UseExcelCellPickerProps) {
  const [cellAddress, setCellAddress] = useState(initialCell);
  const [cellValue, setCellValue] = useState("");
  const [isPickingMode, setIsPickingMode] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const [isReady, setIsReady] = useState(false);
  
  const lastCellRef = useRef<string>("");
  const userClickedRef = useRef<boolean>(false);
  const startTimeRef = useRef<number>(0);
  const savedValueRef = useRef<string | null>(null);
  const isSavingRef = useRef<boolean>(false);

  useEffect(() => {
    if (isOpen && !isVisible) {
      setIsVisible(true);
      setTimeout(() => setIsReady(true), 10);
      isSavingRef.current = false;
      savedValueRef.current = null;
      setIsPickingMode(true);
    } else if (!isOpen && isVisible) {
      setIsReady(false);
      setTimeout(() => setIsVisible(false), 300);
    }
  }, [isOpen, isVisible]);

  useEffect(() => {
    if (isVisible && initialCell) {
      setCellAddress(initialCell);
      setIsPickingMode(false);
    }
  }, [isVisible, initialCell]);

  useEffect(() => {
    if (!isVisible || !isPickingMode) return;
    
    userClickedRef.current = false;
    startTimeRef.current = Date.now();
    
    const getCurrentCell = async () => {
      try {
        await Excel.run(async (context) => {
          const range = context.workbook.getSelectedRange();
          range.load("address");
          await context.sync();
          if (range.address) lastCellRef.current = range.address;
        });
      } catch (error) {
        console.error("Error getting initial cell:", error);
      }
    };
    
    getCurrentCell();
    
    let intervalId: number | null = null;
    let isActive = true;
    
    const checkForClicks = () => {
      if (!isActive || !isPickingMode) {
        if (intervalId) clearInterval(intervalId);
        return;
      }
      
      if (Date.now() - startTimeRef.current < 500) return;
      
      Excel.run(async (context) => {
        const range = context.workbook.getSelectedRange();
        range.load("address");
        if (isColumnPicker) {
          range.load("values");
        }
        await context.sync();
        
        if (!range.address || !isActive) return;
        
        if (range.address !== lastCellRef.current) {
          userClickedRef.current = true;
          setCellAddress(range.address);
          
          if (isColumnPicker && range.values && range.values[0] && range.values[0][0]) {
            setCellValue(String(range.values[0][0]));
          }
          
          setIsPickingMode(false);
          if (intervalId) clearInterval(intervalId);
        }
        
        lastCellRef.current = range.address;
      }).catch(error => console.error("Error checking for cell changes:", error));
    };
    
    intervalId = window.setInterval(checkForClicks, 300);
    
    return () => {
      isActive = false;
      if (intervalId) clearInterval(intervalId);
    };
  }, [isVisible, isPickingMode, isColumnPicker]);

  const closeDialog = (callback?: () => void) => {
    setIsReady(false);
    setTimeout(() => callback?.(), 300);
  };

  const startPicking = () => {
    setIsPickingMode(!isPickingMode);
    userClickedRef.current = false;
    startTimeRef.current = Date.now();
  };

  const getValue = () => {
    return isColumnPicker ? cellValue : cellAddress;
  };

  const clearValue = () => {
    if (isColumnPicker) {
      setCellValue("");
    } else {
      setCellAddress("");
    }
  };

  return {
    cellAddress,
    cellValue,
    isPickingMode,
    isVisible,
    isReady,
    refs: {
      lastCell: lastCellRef,
      userClicked: userClickedRef,
      startTime: startTimeRef,
      savedValue: savedValueRef,
      isSaving: isSavingRef
    },
    setCellAddress,
    setCellValue,
    closeDialog,
    startPicking,
    getValue,
    clearValue
  };
} 