import { Button } from "@/components/ui/buttons";
import { Download } from "lucide-react";
import { useState } from "react";
import { API_BASE_URL } from "@/config/env";

interface DownloadButtonProps {
  className?: string;
  buttonClassName?: string;
  selectClassName?: string;
  variant?: "excel" | "outline" | "default" | "destructive" | "secondary" | "ghost" | "link";
  size?: "default" | "sm" | "lg" | "icon";
  downloadLinks?: {
    json: string;
    csv: string;
  };
}

export const DownloadButton = ({
  className = "",
  buttonClassName = "",
  selectClassName = "",
  variant = "excel",
  size = "sm",
  downloadLinks,
}: DownloadButtonProps) => {
  const [format, setFormat] = useState<"csv" | "json">("csv");

  const handleDownload = () => {
    if (!downloadLinks) {
      console.error("Download links not provided");
      return;
    }

    const selectedLink =
      format === "csv" ? downloadLinks.csv : downloadLinks.json;

    if (!selectedLink || selectedLink.trim() === "") {
      console.error("No link available for selected format:", format);
      return;
    }

    const url = selectedLink.startsWith("http")
      ? selectedLink
      : `${API_BASE_URL}${selectedLink}`;

    console.log("🔗 Opening URL:", url, "for format:", format);

    try {
      window.open(url, "_blank");
    } catch (error) {
      console.error("Failed to open download link:", error);
    }
  };

  if (!downloadLinks) return null;

  return (
    <div className={className}>
      <div className="flex">
        <Button 
          variant={variant} 
          size={size} 
          onClick={handleDownload} 
          className={`rounded-[8px] p-1 w-full flex justify-between items-center overflow-hidden ${buttonClassName}`}
        >
          <div className="flex items-center">
            <Download className="h-4 w-4 mr-1" />
            Download
          </div>
          <select
            value={format}
            onChange={(e) => setFormat(e.target.value as "csv" | "json")}
            onClick={(e) => e.stopPropagation()}
            className={`h-6 text-[10px] rounded bg-transparent text-white max-w-13 ${selectClassName}`}
          >
            <option value="csv" className="bg-gray-800 text-white">CSV</option>
            <option value="json" className="bg-gray-800 text-white">JSON</option>
          </select>
        </Button>
      </div>
    </div>
  );
};
