import { Button } from "@/components/ui/buttons/button";

interface BatchActionsProps {
  batchId: number;
  templateId: number;
  onRerunFails: (batchId: number) => void;
  onViewTemplate: (templateId: number) => void;
  onViewInput: (templateId: number) => void;
  onViewOutput: (templateId: number) => void;
}

export function BatchActions({ 
  batchId, 
  templateId, 
  onRerunFails, 
  onViewTemplate,
  onViewInput,
  onViewOutput
}: BatchActionsProps) {
  const buttonClasses = "text-xs px-2 py-1 h-6";
  
  return (
    <div className="flex gap-1 flex-wrap">
      <Button
        size="sm"
        variant="outline"
        onClick={() => onRerunFails(batchId)}
        className={buttonClasses}
      >
        Re-run fails
      </Button>
      
      <Button
        size="sm"
        variant="outline"
        onClick={() => onViewTemplate(templateId)}
        className={buttonClasses}
      >
        View template
      </Button>
      
      <Button
        size="sm"
        variant="outline"
        onClick={() => onViewInput(templateId)}
        className={buttonClasses}
      >
        View input
      </Button>
      
      <Button
        size="sm"
        variant="outline"
        onClick={() => onViewOutput(templateId)}
        className={buttonClasses}
      >
        View output
      </Button>
    </div>
  );
} 