export const saveTemplatesToMetaSheetAsXML = async (templates: Template[]): Promise<void> => {
  await Excel.run(async (context) => {
    const workbook = context.workbook;
    const metaSheetName = "_BatcherMeta";
    
    let metaSheet;
    try {
      metaSheet = workbook.worksheets.getItem(metaSheetName);
      metaSheet.load(['name']);
      await context.sync();
      
      const usedRange = metaSheet.getUsedRange();
      if (usedRange) {
        usedRange.load(['address']);
        await context.sync();
        usedRange.clear();
      }
    } catch {
      metaSheet = workbook.worksheets.add(metaSheetName);
      await context.sync();
    }
    
    metaSheet.visibility = Excel.SheetVisibility.hidden;
    await context.sync();
    
    let xmlContent = '<?xml version="1.0" encoding="UTF-8"?>\n';
    xmlContent += '<templates>\n';
    
    templates.forEach(template => {
      xmlContent += `  <template id="${template.id}" name="${escapeXml(template.name)}" createdAt="${template.createdAt}">\n`;
      xmlContent += `    <description>${escapeXml(template.description)}</description>\n`;
      
      xmlContent += '    <inputMappings>\n';
      template.inputMappings.forEach(mapping => {
        xmlContent += `      <mapping id="${mapping.id}" column="${escapeXml(mapping.column)}" cell="${mapping.cell}" source="${mapping.source || 'input_file'}"`;
        if (mapping.forcedValue) {
          xmlContent += ` forcedValue="${escapeXml(mapping.forcedValue)}"`;
        }
        xmlContent += '/>\n';
      });
      xmlContent += '    </inputMappings>\n';
      
      xmlContent += '    <outputMappings>\n';
      template.outputMappings.forEach(mapping => {
        xmlContent += `      <mapping id="${mapping.id}" name="${escapeXml(mapping.name)}" cell="${mapping.cell}"/>\n`;
      });
      xmlContent += '    </outputMappings>\n';
      
      xmlContent += '    <identityMappings>\n';
      template.identityMappings.forEach(mapping => {
        xmlContent += `      <mapping id="${mapping.id}" templateId="${mapping.templateId}" name="${escapeXml(mapping.name)}"/>\n`;
      });
      xmlContent += '    </identityMappings>\n';
      
      xmlContent += '    <selectedMappingIds>\n';
      getSelectedMappingIds(template).forEach((id: string) => {
        xmlContent += `      <id>${id}</id>\n`;
      });
      xmlContent += '    </selectedMappingIds>\n';
      
      xmlContent += '  </template>\n';
    });
    
    xmlContent += '</templates>';
    
    const lines = xmlContent.split('\n');
    const range = metaSheet.getRange(`A1:A${lines.length}`);
    range.values = lines.map(line => [line]);
    await context.sync();
  });
};

const escapeXml = (text: string): string => {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}; 