import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogClose,
} from "@/components/ui/feedback/dialog";
import { Input } from "@/components/ui/forms";
import { Textarea } from "@/components/ui/forms/textarea";
import { Button } from "@/components/ui/buttons/button";
import { Alert, AlertDescription } from "@/components/ui/feedback/alert";
import { Template, InputMapping, OutputMapping, getSelectedMappingIds } from "@/types/mapping";
import { getTemplateById, updateTemplate } from "@/services/templateService";
import { toast } from "react-toastify";
import { useExcelTemplate } from "@/hooks/useExcelTemplate";
import { MappingTypeSelect } from "@/components/mapping/MappingTypeSelect";
import { MappingsSection } from "@/components/mapping/MappingsSection";
import { Hash } from "lucide-react"

interface EditTemplateModalProps {
  isOpen: boolean;
  onClose: () => void;
  templateId: string | null;
  onSuccess: () => void;
}

export const EditTemplateModal = ({
  isOpen,
  onClose,
  templateId,
  onSuccess,
}: EditTemplateModalProps) => {
  const [template, setTemplate] = useState<Template | null>(null);
  const [templateName, setTemplateName] = useState("");
  const [description, setDescription] = useState("");
  const [inputMappings, setInputMappings] = useState<InputMapping[]>([]);
  const [outputMappings, setOutputMappings] = useState<OutputMapping[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedMappingIds, setSelectedMappingIds] = useState<string[]>([]);
  const [mappingTypeError, setMappingTypeError] = useState<string>("");
  const { handleCellSelect } = useExcelTemplate();

  useEffect(() => {
    const fetchTemplate = async () => {
      if (!templateId || !isOpen) return;

      try {
        setIsLoading(true);
        setError(null);
        const fetchedTemplate = await getTemplateById(templateId);
        setTemplate(fetchedTemplate);
        setTemplateName(fetchedTemplate.name);
        setDescription(fetchedTemplate.description || "");
        setInputMappings(fetchedTemplate.inputMappings);
        setOutputMappings(fetchedTemplate.outputMappings);
        setSelectedMappingIds(getSelectedMappingIds(fetchedTemplate));
      } catch (err) {
        setError(`Failed to load template: ${(err as Error).message}`);
      } finally {
        setIsLoading(false);
      }
    };

    fetchTemplate();
  }, [templateId, isOpen]);

  const handleSave = async () => {
    if (!template) return;

    if (inputMappings.length > 0) {
      if (!selectedMappingIds.length) {
        setMappingTypeError("Please select at least one mapping type");
        return;
      }

      const selectedMapping = inputMappings.find(
        (m) => m.id === selectedMappingIds[0]
      );
      if (!selectedMapping?.column) {
        setMappingTypeError("Please enter a name for the selected mapping");
        return;
      }
    }
    setMappingTypeError("");

    try {
      setIsSaving(true);
      setError(null);

      await updateTemplate(template.id, {
        name: templateName,
        description: description,
        inputMappings,
        outputMappings,
        identityMappings: selectedMappingIds.map((id) => {
          const mapping = inputMappings.find((m) => m.id === id);
          return { 
            id: crypto.randomUUID(),
            templateId: template.id,
            name: mapping?.column || "" 
          };
        }),
      });

      toast.success("Template updated successfully");
      onSuccess();
      onClose();
    } catch (err) {
      setError(`Failed to update template: ${(err as Error).message}`);
    } finally {
      setIsSaving(false);
    }
  };

  const handleInputMappingDelete = (id: string) => {
    setInputMappings((prevMappings) => 
      prevMappings.filter((mapping) => mapping.id !== id)
    );
    setSelectedMappingIds((prevIds) => 
      prevIds.filter((mappingId) => mappingId !== id)
    );
  };

  const handleAddInputMapping = () => {
    setInputMappings((prev) => [
      ...prev,
      {
        id: crypto.randomUUID(),
        column: "",
        source: "input_file",
        cell: "",
        forcedValue: null,
      },
    ]);
  };

  const handleInputMappingChange = (id: string, field: string, value: string) => {
    setInputMappings((prev) =>
      prev.map((mapping) =>
        mapping.id === id
          ? {
              ...mapping,
              [field === "name" ? "column" : field]: value,
              ...(field === "forcedValue" ? { source: "forced_input" } : {}),
              ...(field === "source" && value === "input_file" ? { forcedValue: null } : {}),
            }
          : mapping
      )
    );
  };

  const handleInputCellSelect = async (id: string) => {
    const result = await handleCellSelect(true);
    if (!result) return;

    const { cell, hasFormula } = result;

    if (hasFormula) {
      toast.error("Cannot use a formula cell as input");
      return;
    }

    setInputMappings((prevMappings) =>
      prevMappings.map((mapping) =>
        mapping.id === id ? { ...mapping, cell } : mapping
      )
    );
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto bg-white">
        <DialogHeader>
          <DialogTitle>Edit Template</DialogTitle>
        </DialogHeader>

        {isLoading ? (
          <div className="flex justify-center py-8">
            <div>Loading template...</div>
          </div>
        ) : error ? (
          <Alert>
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        ) : (
          <div className="space-y-6">
            <div className="grid grid-cols-1 gap-4">
              <div>
                <label className="block text-sm font-medium mb-2">
                  Template Name
                </label>
                <Input
                  value={templateName}
                  onChange={(e) => setTemplateName(e.target.value)}
                  placeholder="Enter template name"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-2">
                  Description
                </label>
                <Textarea
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Enter template description"
                  rows={3}
                />
              </div>
            </div>

              <div className="space-y-6">
                <MappingsSection
                  type="input"
                  mappings={inputMappings}
                  errors={{}}
                  onAdd={handleAddInputMapping}
                  onRemove={handleInputMappingDelete}
                  onChange={handleInputMappingChange}
                  onSelectCell={handleInputCellSelect}
                />

                {inputMappings.length > 0 && (
                  <div className="bg-purple-50 p-4 rounded-lg">
                    <h4 className="font-medium text-sm text-purple-700 mb-3 flex items-center">
                      <Hash className="h-4 w-4 mr-2" />
                      Identity Mappings
                    </h4>
                    <MappingTypeSelect
                      inputMappings={inputMappings}
                      selectedMappingIds={selectedMappingIds}
                      setSelectedMappingIds={setSelectedMappingIds}
                      setMappingTypeError={setMappingTypeError}
                    />
                    {mappingTypeError && (
                      <p className="text-red-500 text-sm mt-2">{mappingTypeError}</p>
                    )}
                  </div>
                )}

                <MappingsSection
                  type="output"
                  mappings={outputMappings}
                  errors={{}}
                  onAdd={() => setOutputMappings(prev => [...prev, {
                    id: crypto.randomUUID(),
                    name: "",
                    cell: ""
                  }])}
                  onRemove={(id) => setOutputMappings(prev => prev.filter(m => m.id !== id))}
                  onChange={(id, field, value) => setOutputMappings(prev => 
                    prev.map(mapping => 
                      mapping.id === id ? { ...mapping, [field]: value } : mapping
                    )
                  )}
                  onSelectCell={async (id) => {
                    const result = await handleCellSelect(false);
                    if (!result) return;
                    const { cell } = result;
                    setOutputMappings(prev => 
                      prev.map(mapping => 
                        mapping.id === id ? { ...mapping, cell } : mapping
                      )
                    );
                  }}
                />
              </div>
          </div>
        )}

        <DialogFooter className="gap-2">
          <DialogClose asChild>
            <Button variant="outline" onClick={onClose} size="sm" className="h-8">
              Cancel
            </Button>
          </DialogClose>
          <Button 
            onClick={handleSave} 
            disabled={isSaving}
            variant="excel"
            size="sm"
            className="h-8"
          >
            {isSaving ? "Saving..." : "Save Changes"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}; 