import { InputMapping, OutputMapping } from "@/types/mapping";
import { Button } from "@/components/ui/buttons";
import { Trash2, Lock, Type } from "lucide-react";
import { MappingCell } from "./MappingCell";

interface MappingRowProps {
  mapping: InputMapping | OutputMapping;
  type: "input" | "output";
  errors: Record<string, string>;
  onChange: (id: string, field: string, value: string) => void;
  onRemove: (id: string) => void;
  onSelectCell: (id: string) => void;
  onSelectColumn?: (id: string) => void;
}

export function MappingRow({ 
  mapping, 
  type, 
  errors, 
  onChange, 
  onRemove, 
  onSelectCell,
  onSelectColumn 
}: MappingRowProps) {
  const cellError = errors[`${type}_cell_${mapping.id}`];
  const hasCellError = !!cellError;

  return (
    <tr className="hover:bg-gray-50">
      <td className="px-4 py-2 border-r border-gray-200">
        <div className="flex items-center gap-1">
          <MappingCell
            value={type === "input" ? (mapping as InputMapping).column || "" : (mapping as OutputMapping).name || ""}
            error={errors[`${type}_name_${mapping.id}`]}
            onChange={(value) => onChange(mapping.id, type === "input" ? "column" : "name", value)}
            type="text"
          />
          {onSelectColumn && (
            <Button
              variant="default"
              size="icon"
              className="h-7 w-7 bg-blue-500 text-white hover:bg-blue-600 flex items-center justify-center text-xs rounded-md ml-1"
              onClick={() => onSelectColumn(mapping.id)}
              title={`Pick ${type === "input" ? "column" : "name"} from cell`}
            >
              <Type size={14} />
            </Button>
          )}
        </div>
      </td>
      {type === "input" && (
        <>
          <td className="px-4 py-2 border-r border-gray-200">
            <MappingCell
              value={(mapping as InputMapping).source || "input_file"}
              error={errors[`${type}_source_${mapping.id}`]}
              onChange={(value) => onChange(mapping.id, "source", value)}
              type="select"
              options={[
                { value: "input_file", label: "Input file" },
                { value: "forced_input", label: "Forced input" }
              ]}
            />
          </td>
          <td className="px-4 py-2 border-r border-gray-200">
            {(mapping as InputMapping).source === "forced_input" ? (
              <MappingCell
                value={(mapping as InputMapping).forcedValue || ""}
                error={errors[`${type}_forcedValue_${mapping.id}`]}
                onChange={(value) => onChange(mapping.id, "forcedValue", value)}
                type="text"
              />
            ) : (
              <div className="flex justify-center items-center h-7">
                <Lock size={18} color="#a3a3a3" />
              </div>
            )}
          </td>
        </>
      )}
      <td className="px-4 py-2 border-r border-gray-200">
        <div>
          <Button
            variant="default"
            className={`h-7 px-2 py-0 rounded-lg border text-[10px] w-full flex items-center justify-center ${
              hasCellError 
                ? "border-red-500 bg-red-50 text-red-700 hover:bg-red-100" 
                : mapping.cell 
                  ? "border-gray-200 bg-gray-100 text-gray-900 hover:bg-gray-200" 
                  : "border-gray-200 bg-white text-gray-700 hover:bg-gray-50"
            }`}
            onClick={() => onSelectCell(mapping.id)}
          >
            {mapping.cell || "Select Cell"}
          </Button>
          {hasCellError && (
            <div className="text-red-500 text-xs mt-1">
              {cellError}
            </div>
          )}
        </div>
      </td>
      <td className="px-4 py-2">
        <div className="flex justify-center">
          <Button
            variant="default"
            size="icon"
            className="h-8 w-8 bg-red-400 text-white hover:bg-red-500 flex items-center justify-center text-sm rounded-md"
            onClick={() => onRemove(mapping.id)}
          >
            <Trash2 size={23} color="#FFF" />
          </Button>
        </div>
      </td>
    </tr>
  );
} 