import { useState } from "react";
import { Button } from "@/components/ui/buttons";
import { InputMapping, OutputMapping } from "@/types/mapping";
import { CellPickerModal } from "./CellPickerModal";
import { MappingsTable } from "./MappingsTable";

interface MappingsSectionProps {
  type: "input" | "output";
  mappings: (InputMapping | OutputMapping)[];
  errors: Record<string, string>;
  onAdd: () => void;
  onRemove: (id: string) => void;
  onSelectCell: (id: string) => void;
  onChange: (id: string, field: string, value: string) => void;
}

export function MappingsSection({
  type,
  mappings,
  errors,
  onAdd,
  onRemove,
  onChange,
}: MappingsSectionProps) {
  const [selectedMappingId, setSelectedMappingId] = useState<string | null>(null);
  const [isColumnPicker, setIsColumnPicker] = useState(false);

  const handleCellSelect = (id: string) => {
    setSelectedMappingId(id);
    setIsColumnPicker(false);
  };

  const handleColumnSelect = (id: string) => {
    setSelectedMappingId(id);
    setIsColumnPicker(true);
  };

  const handleCellSelected = (value: string, mappingId: string) => {
    if (isColumnPicker) {
      onChange(mappingId, type === "input" ? "column" : "name", value);
    } else {
      onChange(mappingId, "cell", value);
    }
    setSelectedMappingId(null);
    setIsColumnPicker(false);
  };

  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center">
        <h3 className="font-semibold">{type === "input" ? "Input" : "Output"} Mappings</h3>
        <Button
          variant="default"
          className="text-3xl p-3 text-green-600 border bg-white rounded-xl text-center"
          onClick={onAdd}
        >
          +
        </Button>
      </div>

      <MappingsTable
        type={type}
        mappings={mappings}
        errors={errors}
        onChange={onChange}
        onRemove={onRemove}
        onSelectCell={handleCellSelect}
        onSelectColumn={handleColumnSelect}
      />

      <CellPickerModal
        isOpen={!!selectedMappingId}
        onClose={() => {
          setSelectedMappingId(null);
          setIsColumnPicker(false);
        }}
        onSelect={handleCellSelected}
        initialCell={selectedMappingId ? 
          (isColumnPicker ? "" : mappings.find(m => m.id === selectedMappingId)?.cell || "") : 
          ""
        }
        mappingId={selectedMappingId || ""}
        isColumnPicker={isColumnPicker}
      />
    </div>
  );
} 