import { X } from "lucide-react";

interface CellInputsProps {
  isColumnPicker: boolean;
  cellAddress: string;
  cellValue: string;
  onCellAddressChange: (value: string) => void;
  onCellValueChange: (value: string) => void;
  onClear: () => void;
}

export function CellInputs({
  isColumnPicker,
  cellAddress,
  cellValue,
  onCellAddressChange,
  onCellValueChange,
  onClear
}: CellInputsProps) {
  return (
    <div className="space-y-2">
      {isColumnPicker ? (
        <>
          <label className="block text-sm font-medium text-gray-700">
            Column Name
          </label>
          <div className="space-y-2">
            <div className="relative">
              <input
                type="text"
                value={cellValue}
                onChange={(e) => onCellValueChange(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md bg-gray-50 text-sm pr-8"
                placeholder="Cell value will appear here"
              />
              {cellValue && (
                <button
                  type="button"
                  onClick={onClear}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                >
                  <X size={14} />
                </button>
              )}
            </div>
            <div className="text-xs text-gray-500">
              From cell: {cellAddress || "No cell selected"}
            </div>
          </div>
        </>
      ) : (
        <>
          <label className="block text-sm font-medium text-gray-700">Reference</label>
          <div className="relative">
            <input
              type="text"
              value={cellAddress}
              onChange={(e) => onCellAddressChange(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md bg-gray-50 text-sm pr-8"
              placeholder="Enter cell reference (e.g. A1)"
            />
            {cellAddress && (
              <button
                type="button"
                onClick={onClear}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                <X size={14} />
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
} 