const isDev = import.meta.env.DEV;
const isProd = import.meta.env.PROD;

const useHttps = window.location.protocol === 'https:';

export const API_BASE_URL = isDev 
  ? import.meta.env.VITE_API_BASE_URL || 'https://exbatch-back-end-sql-lite.onrender.com'
  : 'http://localhost:8000';

export const APP_BASE_URL = isDev
  ? import.meta.env.VITE_APP_URL || 'http://localhost:3000'
  : 'http://localhost:8000';

export const config = {
  apiBaseUrl: API_BASE_URL,
  appBaseUrl: APP_BASE_URL,
  isDev,
  isProd,
  useHttps,
  addinId: import.meta.env.VITE_ADDIN_ID,
  addinVersion: import.meta.env.VITE_ADDIN_VERSION,
  providerName: import.meta.env.VITE_PROVIDER_NAME,
  displayName: import.meta.env.VITE_DISPLAY_NAME,
  description: import.meta.env.VITE_DESCRIPTION,
  iconUrl32: import.meta.env.VITE_ICON_URL_32,
  iconUrl64: import.meta.env.VITE_ICON_URL_64,
  supportUrl: import.meta.env.VITE_SUPPORT_URL,
}; 