import { InputMapping, OutputMapping } from "@/types/mapping";
import { MappingRow } from "./MappingRow";

interface MappingsTableProps {
  type: "input" | "output";
  mappings: (InputMapping | OutputMapping)[];
  errors: Record<string, string>;
  onChange: (id: string, field: string, value: string) => void;
  onRemove: (id: string) => void;
  onSelectCell: (id: string) => void;
  onSelectColumn?: (id: string) => void;
}

export function MappingsTable({ type, mappings, errors, onChange, onRemove, onSelectCell, onSelectColumn }: MappingsTableProps) {
  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="bg-gray-700 text-white">
              <th className="px-4 py-2 text-center text-xs font-semibold border-r border-gray-600">
                {type === "input" ? "Column" : "Name"}
              </th>
              {type === "input" && (
                <>
                  <th className="px-4 py-2 text-center text-xs font-semibold border-r border-gray-600">Source</th>
                  <th className="px-4 py-2 text-center text-xs font-semibold border-r border-gray-600">Forced Value</th>
                </>
              )}
              <th className="px-4 py-2 text-center text-xs font-semibold border-r border-gray-600">Cell</th>
              <th className="px-4 py-2 text-center text-xs font-semibold w-24">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {mappings.map((mapping) => (
              <MappingRow
                key={mapping.id}
                mapping={mapping}
                type={type}
                errors={errors}
                onChange={onChange}
                onRemove={onRemove}
                onSelectCell={onSelectCell}
                onSelectColumn={onSelectColumn}
              />
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
} 