import { useState, useCallback } from 'react';
import { getActiveWorkbookInfo } from '@/lib/excel/office';
import { useExcelFileStore } from '@/store/excelFile';

export const useExcelFile = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { currentFile, setCurrentFile, clearCurrentFile } = useExcelFileStore();

  const loadCurrentFile = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    
    try {
      const fileInfo = await getActiveWorkbookInfo();
      setCurrentFile(fileInfo);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load file info');
      clearCurrentFile();
    } finally {
      setIsLoading(false);
    }
  }, [setCurrentFile, clearCurrentFile]);

  return {
    currentFile,
    isLoading,
    error,
    loadCurrentFile,
    clearCurrentFile
  };
}; 