import { ReactNode } from "react";

interface TableCellProps {
  children: ReactNode;
  className?: string;
  isLast?: boolean;
}

export function TableCell({ children, className = "", isLast = false }: TableCellProps) {
  const borderClass = isLast ? "" : "border-r border-gray-200";
  
  return (
    <td className={`px-2 py-2 ${borderClass} ${className}`}>
      {children}
    </td>
  );
} 