import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/feedback/dialog";
import { ReadOnlyMappingsSection } from "@/components/shared/ReadOnlyMappingsSection";
import { getTemplateById } from "@/services/templateService";
import { Template } from "@/types/mapping";
import { LoadingState } from "@/components/shared/LoadingState";
import { ErrorState } from "@/components/shared/ErrorState";

interface ViewMappingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  templateId: string | null;
  type: "input" | "output";
}

export function ViewMappingsModal({ isOpen, onClose, templateId, type }: ViewMappingsModalProps) {
  const [template, setTemplate] = useState<Template | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!isOpen) {
      const timeout = setTimeout(() => {
        setTemplate(null);
        setError(null);
        setLoading(false);
      }, 150);
      return () => clearTimeout(timeout);
    }

    if (!templateId) {
      setTemplate(null);
      setError(null);
      return;
    }

    const fetchTemplate = async () => {
      setLoading(true);
      setError(null);
      
      try {
        const templateData = await getTemplateById(templateId);
        setTemplate(templateData);
      } catch (err) {
        setError((err as Error).message);
      } finally {
        setLoading(false);
      }
    };

    fetchTemplate();
  }, [isOpen, templateId]);

  const mappings = template ? (type === "input" ? template.inputMappings : template.outputMappings) : [];
  const title = `Template ${type === "input" ? "Input" : "Output"} Mappings`;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl bg-white max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {title}
            {template && ` - ${template.name}`}
          </DialogTitle>
        </DialogHeader>

        <div className="mt-4">
          {loading && <LoadingState message="Loading template..." />}
          
          {error && (
            <ErrorState 
              error={error} 
              onRetry={() => {
                if (templateId) {
                  setError(null);
                  setLoading(true);
                  getTemplateById(templateId)
                    .then(setTemplate)
                    .catch((err: Error) => setError(err.message))
                    .finally(() => setLoading(false));
                }
              }} 
            />
          )}
          
          {template && !loading && !error && (
            <ReadOnlyMappingsSection
              type={type}
              mappings={mappings}
            />
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
} 