/**
 * Function for processing CSV files
 */

/**
 * Parses a CSV file into a two-dimensional array
 * @param file CSV file to parse
 * @returns Promise with a two-dimensional array containing CSV data
 */
export const parseCsvFile = async (file: File): Promise<string[][]> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    
    reader.onload = (event) => {
      try {
        const csv = event.target?.result as string;
        if (!csv) {
          reject(new Error("Failed to read CSV file"));
          return;
        }
        
        // Detect delimiter - comma is default, but check for semicolon which is common in Europe
        let delimiter = ',';
        const firstLine = csv.split(/\r\n|\n/)[0];
        if (firstLine && firstLine.includes(';') && !firstLine.includes(',')) {
          delimiter = ';';
        }
        
        // Split by rows
        const lines = csv.split(/\r\n|\n/);
        
        // Parse each row
        const result: string[][] = [];
        for (let i = 0; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue; // Skip empty lines
          
          // Parse CSV line with proper handling of quoted fields
          const values: string[] = [];
          let current = '';
          let inQuotes = false;
          
          for (let j = 0; j < line.length; j++) {
            const char = line[j];
            const nextChar = line[j + 1];
            
            // Handle quotes
            if (char === '"') {
              // If we're at the opening quote or closing quote
              if (!inQuotes) {
                inQuotes = true;
                continue; // Skip the opening quote
              } else if (nextChar === delimiter || nextChar === undefined) {
                // This is a closing quote followed by delimiter or end of line
                inQuotes = false;
                continue; // Skip the closing quote
              } else if (nextChar === '"') {
                // This is an escaped quote inside a quoted field
                j++; // Skip the next quote character (escaped quote)
                current += '"';
                continue;
              } else {
                // Toggle quote state
                inQuotes = !inQuotes;
                continue;
              }
            }
            
            // Handle delimiters
            if (char === delimiter && !inQuotes) {
              // End of field, add to values
              values.push(current);
              current = '';
              continue;
            }
            
            // Add character to current field
            current += char;
          }
          
          // Add last value
          values.push(current);
          
          // Add row to result
          result.push(values);
        }
        
        resolve(result);
      } catch (error) {
        reject(error);
      }
    };
    
    reader.onerror = () => {
      reject(new Error("Error reading CSV file"));
    };
    
    reader.readAsText(file, 'utf-8-sig');
  });
}; 