import { useEffect } from "react";
import { Button } from "@/components/ui/buttons";
import { useExcelCellPicker } from "@/hooks/useExcelCellPicker";
import { CellPickerHeader } from "./CellPickerHeader";
import { CellInputs } from "./CellInputs";
import { PickButton } from "./PickButton";
import { PickingInstructions } from "./PickingInstructions";

interface CellPickerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (cell: string, mappingId: string) => void;
  initialCell?: string;
  mappingId: string;
  isColumnPicker?: boolean;
}

export function CellPickerModal({
  isOpen,
  onClose,
  onSelect,
  initialCell = "",
  mappingId,
  isColumnPicker = false,
}: CellPickerModalProps) {
  const picker = useExcelCellPicker({ 
    isOpen, 
    isColumnPicker, 
    initialCell 
  });

  const handleSave = () => {
    const value = picker.getValue();
    if (!value || picker.refs.isSaving.current) return;
    
    picker.refs.isSaving.current = true;
    picker.refs.savedValue.current = value;
    
    picker.closeDialog(() => {
      if (picker.refs.savedValue.current) {
        onSelect(picker.refs.savedValue.current, mappingId);
        onClose();
        picker.refs.isSaving.current = false;
        picker.refs.savedValue.current = null;
      }
    });
  };

  const handleCancel = () => picker.closeDialog(onClose);
  
  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) picker.closeDialog(onClose);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && picker.isVisible) picker.closeDialog(onClose);
    };
    
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [picker.isVisible, onClose, picker]);

  if (!picker.isVisible) return null;
  
  return (
    <div 
      className={`fixed inset-0 flex items-center justify-center z-50 bg-black/50 transition-opacity duration-300 ${
        picker.isReady ? 'opacity-100' : 'opacity-0'
      }`}
      onClick={handleBackdropClick}
      aria-modal="true"
      role="dialog"
    >
      <div 
        className={`max-w-md w-full bg-white border-green-600 rounded-lg shadow-lg transform transition-transform duration-300 ${
          picker.isReady ? 'translate-y-0' : 'translate-y-8'
        }`}
        onClick={(e) => e.stopPropagation()}
      >
        <CellPickerHeader isColumnPicker={isColumnPicker} />

        <div className="py-4 px-6 space-y-4">
          {!picker.isPickingMode && !picker.cellAddress && (
            <div className="p-3 bg-blue-50 border border-blue-200 rounded-md text-blue-700 text-sm space-y-2">
              <p>Click the <strong>"Pick Cell"</strong> button to select a cell from Excel spreadsheet</p>
            </div>
          )}
          
          <CellInputs
            isColumnPicker={isColumnPicker}
            cellAddress={picker.cellAddress}
            cellValue={picker.cellValue}
            onCellAddressChange={picker.setCellAddress}
            onCellValueChange={picker.setCellValue}
            onClear={picker.clearValue}
          />

          <PickButton
            isPickingMode={picker.isPickingMode}
            onTogglePicking={picker.startPicking}
          />
          
          <PickingInstructions
            isPickingMode={picker.isPickingMode}
            isColumnPicker={isColumnPicker}
          />
        </div>

        <div className="border-t border-gray-200 pt-3 pb-4 px-6 flex justify-end gap-2">
          <Button
            variant="outline"
            onClick={handleCancel}
            className="text-sm border-gray-300 hover:bg-gray-50"
          >
            Cancel
          </Button>
          <Button
            variant="default"
            onClick={handleSave}
            className="text-sm bg-green-600 hover:bg-green-700 text-white shadow-sm"
            disabled={
              picker.isPickingMode || 
              (isColumnPicker ? !picker.cellValue : !picker.cellAddress)
            }
          >
            Save
          </Button>
        </div>
      </div>
    </div>
  );
} 