export interface ExcelFileInfo {
  name: string;
}

export const getActiveWorkbookInfo = async (): Promise<ExcelFileInfo> => {
  return await Excel.run(async (context) => {
    const workbook = context.workbook;
    workbook.load(['name']);
    await context.sync();
    
    return {
      name: workbook.name || "Unknown file"
    };
  });
};

export const getSelectedRange = async () => {
  const range = await Excel.run(async (context) => {
    const range = context.workbook.getSelectedRange();
    range.load('address');
    await context.sync();
    return range;
  });
  return range;
};

export const writeToRange = async (value: string) => {
  await Excel.run(async (context) => {
    const range = context.workbook.getSelectedRange();
    range.values = [[value]];
    await context.sync();
  });
}; 