import { BatchRun } from "@/types/batch";
import { formatDateTime } from "@/utils/batchUtils";
import { DownloadButton } from "@/components/templates/DownloadButton";
import { TableCell } from "@/components/shared/TableCell";
import { BatchActions } from "@/components/shared/BatchActions";

interface BatchRunRowProps {
  row: BatchRun;
  isSelected: boolean;
  onSelectRow: (id: number) => void;
  onRerunFails: (batchId: number) => void;
  onViewTemplate: (templateId: number) => void;
  onViewInput: (templateId: number) => void;
  onViewOutput: (templateId: number) => void;
}

export function BatchRunRow({ 
  row, 
  isSelected, 
  onSelectRow, 
  onRerunFails, 
  onViewTemplate,
  onViewInput,
  onViewOutput
}: BatchRunRowProps) {
  const textClasses = "text-xs";
  const monoClasses = "text-xs font-mono";
  const truncateClasses = "text-xs truncate";
  
  const hasDownloadLinks = row.download_link_csv || row.download_link_json;
  
  return (
    <tr className="hover:bg-gray-50">
      <TableCell>
        <input
          type="checkbox"
          checked={isSelected}
          onChange={() => onSelectRow(row.id)}
          className="rounded"
        />
      </TableCell>
      
      <TableCell className={monoClasses}>
        {row.id}
      </TableCell>
      
      <TableCell className={monoClasses}>
        {row.template_id}
      </TableCell>
      
      <TableCell className={truncateClasses}>
        {row.excel_filename}
      </TableCell>
      
      <TableCell className={truncateClasses}>
        {row.csv_filename}
      </TableCell>
      
      <TableCell className={textClasses}>
        {formatDateTime(row.datetime_started)}
      </TableCell>
      
      <TableCell className={textClasses}>
        {formatDateTime(row.datetime_ended)}
      </TableCell>
      
      <TableCell className={monoClasses}>
        {row.duration_seconds}s
      </TableCell>
      
      <TableCell className={monoClasses}>
        {row.num_of_records.toLocaleString()}
      </TableCell>
      
      <TableCell className={monoClasses}>
        {row.processed_records.toLocaleString()}
      </TableCell>
      
      <TableCell className={monoClasses}>
        {(row.num_of_records - row.processed_records).toLocaleString()}
      </TableCell>
      
      <TableCell>
        {hasDownloadLinks ? (
          <DownloadButton
            downloadLinks={{
              csv: row.download_link_csv || "",
              json: row.download_link_json || ""
            }}
            className="text-xs"
          />
        ) : (
          <span className="text-gray-400">—</span>
        )}
      </TableCell>
      
      <TableCell isLast>
        <BatchActions
          batchId={row.id}
          templateId={row.template_id}
          onRerunFails={onRerunFails}
          onViewTemplate={onViewTemplate}
          onViewInput={onViewInput}
          onViewOutput={onViewOutput}
        />
      </TableCell>
    </tr>
  );
} 