import { Template } from "@/types/mapping";
import { 
  saveTemplatesToMetaSheet, 
  loadTemplatesFromMetaSheet, 
  checkMetaSheetExists 
} from "@/lib/excel/office";
import { generateNumericId, initializeIdCounter } from "@/utils/idGenerator";

export const getTemplates = async (): Promise<Template[]> => {
  try {
    const templates = await loadTemplatesFromMetaSheet();
    
    const allIds = templates.flatMap(t => [
      t.id,
      ...t.inputMappings.map(m => m.id),
      ...t.outputMappings.map(m => m.id),
      ...t.identityMappings.map(m => m.id)
    ]);
    initializeIdCounter(allIds);
    
    return templates;
  } catch (error) {
    console.error('Failed to load templates from Excel:', error);
    return [];
  }
};

export const getTemplateById = async (templateId: string): Promise<Template> => {
  try {
    const templates = await loadTemplatesFromMetaSheet();
    const template = templates.find(t => t.id === templateId);
    
    if (!template) {
      throw new Error(`Template with ID ${templateId} not found`);
    }
    
    return template;
  } catch (error) {
    throw new Error(`Failed to get template: ${(error as Error).message}`);
  }
};

export const createTemplate = async (template: Omit<Template, "id" | "createdAt">): Promise<Template> => {
  try {
    const templates = await loadTemplatesFromMetaSheet();
    
    const allIds = templates.flatMap(t => [
      t.id,
      ...t.inputMappings.map(m => m.id),
      ...t.outputMappings.map(m => m.id),
      ...t.identityMappings.map(m => m.id)
    ]);
    initializeIdCounter(allIds);
    
    const newTemplate: Template = {
      ...template,
      id: generateNumericId(),
      createdAt: new Date().toISOString()
    };
    
    const updatedTemplates = [...templates, newTemplate];
    await saveTemplatesToMetaSheet(updatedTemplates);
    
    return newTemplate;
  } catch (error) {
    throw new Error(`Template creation failed: ${(error as Error).message}`);
  }
};

export const updateTemplate = async (templateId: string, updatedData: Partial<Template>): Promise<void> => {
  try {
    const templates = await loadTemplatesFromMetaSheet();
    const templateIndex = templates.findIndex(t => t.id === templateId);
    
    if (templateIndex === -1) {
      throw new Error(`Template with ID ${templateId} not found`);
    }
    
    templates[templateIndex] = {
      ...templates[templateIndex],
      ...updatedData,
      id: templateId
    };
    
    await saveTemplatesToMetaSheet(templates);
  } catch (error) {
    throw new Error(`Template update failed: ${(error as Error).message}`);
  }
};

export const deleteTemplate = async (templateId: string): Promise<void> => {
  try {
    const templates = await loadTemplatesFromMetaSheet();
    const filteredTemplates = templates.filter(t => t.id !== templateId);
    
    if (templates.length === filteredTemplates.length) {
      throw new Error(`Template with ID ${templateId} not found`);
    }
    
    await saveTemplatesToMetaSheet(filteredTemplates);
  } catch (error) {
    throw new Error(`Template deletion failed: ${(error as Error).message}`);
  }
};

export const checkTemplatesExist = async (): Promise<boolean> => {
  try {
    return await checkMetaSheetExists();
  } catch (error) {
    console.error('Failed to check if templates exist:', error);
    return false;
  }
}; 