import { useState, useEffect } from "react"
import { Page, Mode, DEFAULT_PAGE, DEFAULT_MODE } from "@/constants/navigation"

export const useNavigation = () => {
  const [currentPage, setCurrentPage] = useState<Page>(DEFAULT_PAGE)
  const [mode, setMode] = useState<Mode>(DEFAULT_MODE)
  const [params, setParams] = useState<Record<string, string>>({})

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash
      const [path, queryString] = hash.split('?')
      const urlParams = new URLSearchParams(queryString)
      const urlMode = urlParams.get('mode') as Mode
      const urlTemplate = urlParams.get('template')
      
      const newParams: Record<string, string> = {}
      
      if (urlTemplate) {
        newParams.template = urlTemplate
      }
      
      for (const [key, value] of urlParams.entries()) {
        if (key !== 'mode') {
          newParams[key] = value
        }
      }
      
      setParams(newParams)

      if (path.startsWith("#batch")) {
        setCurrentPage(Page.BATCH)
      } else if (path.startsWith("#templates-list")) {
        setCurrentPage(Page.TEMPLATES_LIST)
      } else if (path.startsWith("#run-template")) {
        setCurrentPage(Page.RUN_TEMPLATE)
      } else if (path.startsWith("#template")) {
        setCurrentPage(Page.TEMPLATE)
        if (urlMode === Mode.USE || urlMode === Mode.CREATE) {
          setMode(urlMode)
        }
      } else {
        setCurrentPage(Page.BATCH)
      }
    }

    // Initial check
    handleHashChange()

    // Listen for hash changes
    window.addEventListener("hashchange", handleHashChange)
    return () => window.removeEventListener("hashchange", handleHashChange)
  }, [])

  const navigateTo = (page: Page, mode?: Mode, customParams?: Record<string, string>) => {
    let hashValue = page === Page.BATCH ? "" : page
    
    // Build query string with parameters
    const queryParams: string[] = []
    
    if (mode) {
      queryParams.push(`mode=${mode}`)
    }
    
    if (customParams) {
      Object.entries(customParams).forEach(([key, value]) => {
        queryParams.push(`${key}=${encodeURIComponent(value)}`)
      })
    }
    
    // Add query string if we have parameters
    if (queryParams.length > 0) {
      hashValue += `?${queryParams.join('&')}`
    }
    
    // Handle special case for full paths
    if (page.startsWith('#') || page.startsWith('/')) {
      hashValue = page.startsWith('#') ? page.substring(1) : page
    }
    
    window.location.hash = hashValue
  }

  return {
    currentPage,
    mode,
    params,
    navigateTo
  }
} 