import { API_BASE_URL } from "@/config/env";

interface ApiResponse<T> {
  data?: T;
  error?: string;
  errorDetails?: Record<string, unknown>;
}

// Common headers for all requests
const getCommonHeaders = (): Record<string, string> => ({
  'Cache-Control': 'no-cache, no-store',
  'Pragma': 'no-cache'
});

// Handle API response and parse data or errors
const handleResponse = async <T>(response: Response): Promise<ApiResponse<T>> => {
  if (!response.ok) {
    try {
      const errorData = await response.json();
      
      if (response.status === 422) {
        return {
          error: errorData.detail ? 
            (Array.isArray(errorData.detail) ? 
              `Validation Error: ${JSON.stringify(errorData.detail)}` : 
              errorData.detail) : 
            `HTTP error! status: ${response.status}`,
          errorDetails: errorData
        };
      }
      
      return {
        error: errorData.message || errorData.detail || `HTTP error! status: ${response.status}`,
        errorDetails: errorData
      };
    } catch {
      return {
        error: `HTTP error! status: ${response.status}`,
      };
    }
  }

  if (response.status === 204 || response.headers.get('content-length') === '0') {
    return { data: undefined as T };
  }

  try {
    const contentType = response.headers.get('content-type');
    const text = await response.text();
    
    if (!text) {
      return { data: undefined as T };
    }
    
    // If response is CSV, return it as is
    if (contentType?.includes('text/csv')) {
      return { 
        data: {
          success: true,
          file_url: URL.createObjectURL(new Blob([text], { type: 'text/csv' })),
          content: text
        } as T 
      };
    }
    
    // Try to parse as JSON
    const data = JSON.parse(text);
    return { data };
  } catch {
    return {
      error: 'Failed to parse response',
    };
  }
};

// Create a fetch request with error handling
const fetchWithErrorHandling = async <T>(
  url: string,
  options: RequestInit
): Promise<ApiResponse<T>> => {
  try {
    const response = await fetch(url, options);
    return handleResponse<T>(response);
  } catch (error) {
    return {
      error: (error as Error).message || 'Network error occurred',
    };
  }
};

// GET request
export const apiGet = async <T>(endpoint: string): Promise<ApiResponse<T>> => {
  const url = `${API_BASE_URL}${endpoint}`;
  
  return fetchWithErrorHandling<T>(url, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      ...getCommonHeaders()
    },
  });
};

// POST request
export const apiPost = async <T>(
  endpoint: string, 
  data: object | FormData, 
  isFormData = false
): Promise<ApiResponse<T>> => {
  const url = `${API_BASE_URL}${endpoint}`;
  const headers: Record<string, string> = { ...getCommonHeaders() };
  let body: string | FormData;
  
  if (isFormData && data instanceof FormData) {
    body = data;
    // Don't set Content-Type for FormData, let browser set it with boundary
  } else {
    headers['Content-Type'] = 'application/json';
    body = JSON.stringify(data);
  }
  
  return fetchWithErrorHandling<T>(url, {
    method: 'POST',
    headers,
    body,
  });
};
    
// DELETE request
export const apiDelete = async <T>(endpoint: string): Promise<ApiResponse<T>> => {
  const url = `${API_BASE_URL}${endpoint}`;
  
  return fetchWithErrorHandling<T>(url, {
      method: 'DELETE',
      headers: {
        'Content-Type': 'application/json',
      ...getCommonHeaders()
      },
    });
};

