import { BatchRun } from "@/types/batch";
import { TableColumn } from "@/components/ui/layout/table";
import { SortableHeader } from "@/components/shared/SortableHeader";

type SortField = keyof BatchRun;
type SortDirection = "asc" | "desc";

interface BatchTableColumnsProps {
  sortField: SortField;
  sortDirection: SortDirection;
  handleSort: (field: SortField) => void;
  handleSelectAll: (data: BatchRun[]) => void;
  isAllSelected: (data: BatchRun[]) => boolean;
  visibleData: BatchRun[];
}

export const useBatchTableColumns = ({
  sortField,
  sortDirection,
  handleSort,
  handleSelectAll,
  isAllSelected,
  visibleData
}: BatchTableColumnsProps): TableColumn<BatchRun>[] => {
  const createSortableHeader = (field: SortField, title: string) => (
    <SortableHeader 
      field={field} 
      currentField={sortField} 
      direction={sortDirection} 
      onSort={handleSort}
    >
      {title}
    </SortableHeader>
  );

  return [
    {
      key: "select",
      title: (
        <input
          type="checkbox"
          checked={isAllSelected(visibleData)}
          onChange={() => handleSelectAll(visibleData)}
          className="rounded"
        />
      ),
      className: "w-12"
    },
    {
      key: "id", 
      title: createSortableHeader("id", "Batch ID"),
      className: "w-32"
    },
    {
      key: "template_id",
      title: createSortableHeader("template_id", "Template ID"), 
      className: "w-32"
    },
    {
      key: "excel_filename",
      title: createSortableHeader("excel_filename", "Excel File"),
      className: "w-48"
    },
    {
      key: "csv_filename",
      title: createSortableHeader("csv_filename", "CSV File"),
      className: "w-48"
    },
    {
      key: "datetime_started",
      title: createSortableHeader("datetime_started", "Started At"),
      className: "w-44"
    },
    {
      key: "datetime_ended",
      title: createSortableHeader("datetime_ended", "Ended At"),
      className: "w-44"
    },
    {
      key: "duration_seconds",
      title: createSortableHeader("duration_seconds", "Duration (s)"),
      className: "w-32"
    },
    {
      key: "num_of_records",
      title: createSortableHeader("num_of_records", "Total Records"),
      className: "w-32"
    },
    {
      key: "processed_records",
      title: createSortableHeader("processed_records", "Processed"),
      className: "w-32"
    },
    {
      key: "failed_records",
      title: "Failed Records",
      className: "w-32"
    },
    {
      key: "result",
      title: "Result",
      className: "w-40"
    },
    {
      key: "actions",
      title: "Actions", 
      className: "w-64"
    }
  ];
}; 