let currentId = 1;

export const generateNumericId = (): string => {
  return (currentId++).toString();
};

export const initializeIdCounter = (existingIds: string[]): void => {
  const numericIds = existingIds
    .map(id => parseInt(id))
    .filter(id => !isNaN(id));
  
  if (numericIds.length > 0) {
    currentId = Math.max(...numericIds) + 1;
  } else {
    currentId = 1;
  }
};

export const resetIdCounter = (): void => {
  currentId = 1;
}; 