import { Button } from "@/components/ui/buttons/button";

interface LoadMoreSectionProps {
  hasMore: boolean;
  remainingCount: number;
  onLoadMore: () => void;
}

export function LoadMoreSection({ hasMore, remainingCount, onLoadMore }: LoadMoreSectionProps) {
  if (!hasMore) return null;
  
  return (
    <div className="p-4 text-center border-t border-gray-200 bg-white rounded-b-lg">
      <Button variant="outline" onClick={onLoadMore}>
        Load more ({remainingCount} remaining)
      </Button>
    </div>
  );
} 