import { useCallback, useState } from "react";
import { BatchRun } from "@/types/batch";
import { GenericTable } from "@/components/ui/layout/table";
import { BatchRunRow } from "@/components/BatchRunRow";
import { useSorting, useRowSelection, usePagination, useBatchRuns } from "@/hooks";
import { batchActions } from "@/utils";
import { EditTemplateModal } from "@/components/templates/EditTemplateModal";
import { ViewMappingsModal } from "@/components/shared/ViewMappingsModal";
import { LoadingState } from "@/components/shared/LoadingState";
import { ErrorState } from "@/components/shared/ErrorState";
import { EmptyState } from "@/components/shared/EmptyState";
import { BatchRunsHeader } from "@/components/shared/BatchRunsHeader";
import { LoadMoreSection } from "@/components/shared/LoadMoreSection";
import { useBatchTableColumns } from "@/components/shared/BatchTableColumns";

export const BatchRunsTab = () => {
  const { data, loading, error, isEmpty, deleteBatchRuns } = useBatchRuns();
  const [viewModalOpen, setViewModalOpen] = useState(false);
  const [viewMappingsModalOpen, setViewMappingsModalOpen] = useState(false);
  const [mappingsType, setMappingsType] = useState<"input" | "output">("input");
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
  
  const { sortedData, sortField, sortDirection, handleSort } = useSorting(data, "id");
  const { selectedRows, handleSelectRow, handleSelectAll, clearSelection, isSelected, isAllSelected } = useRowSelection<BatchRun>();
  const { visibleData, hasMore, remainingCount, loadMore } = usePagination(sortedData, 50);

  const columns = useBatchTableColumns({
    sortField: sortField || "id",
    sortDirection,
    handleSort,
    handleSelectAll,
    isAllSelected,
    visibleData
  });

  const handleDelete = useCallback(async () => {
    if (selectedRows.size === 0) return;
    
    const selectedIds = Array.from(selectedRows);
    await deleteBatchRuns(selectedIds);
    clearSelection();
  }, [selectedRows, clearSelection, deleteBatchRuns]);

  const handleViewTemplate = useCallback((templateId: number) => {
    setSelectedTemplateId(templateId.toString());
    setViewModalOpen(true);
  }, []);

  const handleViewInput = useCallback((templateId: number) => {
    setSelectedTemplateId(templateId.toString());
    setMappingsType("input");
    setViewMappingsModalOpen(true);
  }, []);

  const handleViewOutput = useCallback((templateId: number) => {
    setSelectedTemplateId(templateId.toString());
    setMappingsType("output");
    setViewMappingsModalOpen(true);
  }, []);

  const handleCloseTemplateModal = useCallback(() => {
    setViewModalOpen(false);
    setTimeout(() => setSelectedTemplateId(null), 150);
  }, []);

  const handleCloseMappingsModal = useCallback(() => {
    setViewMappingsModalOpen(false);
    setTimeout(() => setSelectedTemplateId(null), 150);
  }, []);

  const renderRow = (row: BatchRun) => (
    <BatchRunRow
      key={row.id}
      row={row}
      isSelected={isSelected(row.id)}
      onSelectRow={handleSelectRow}
      onRerunFails={batchActions.rerunFails}
      onViewTemplate={handleViewTemplate}
      onViewInput={handleViewInput}
      onViewOutput={handleViewOutput}
    />
  );

  if (loading && data.length === 0) {
    return <LoadingState message="Loading batch runs..." />;
  }

  if (error) {
    return <ErrorState error={error} onRetry={() => window.location.reload()} />;
  }

  if (isEmpty && !loading) {
    return (
      <EmptyState 
        title="No batch runs found"
        description="There are no batch processing logs available."
      />
    );
  }

  return (
    <div className="space-y-4">
      <BatchRunsHeader
        totalCount={data.length}
        selectedCount={selectedRows.size}
        isLoading={loading}
        onDelete={handleDelete}
      />

      <GenericTable
        columns={columns}
        data={visibleData}
        renderRow={renderRow}
        maxHeight="600px"
        className="relative overflow-x-auto"
      />
      
      <LoadMoreSection
        hasMore={hasMore}
        remainingCount={remainingCount}
        onLoadMore={loadMore}
      />
      
      <EditTemplateModal
        isOpen={viewModalOpen}
        onClose={handleCloseTemplateModal}
        templateId={selectedTemplateId}
        onSuccess={() => {}}
      />

      <ViewMappingsModal
        isOpen={viewMappingsModalOpen}
        onClose={handleCloseMappingsModal}
        templateId={selectedTemplateId}
        type={mappingsType}
      />
    </div>
  );
}; 