import { Template } from "@/types/mapping";

interface IdentityMappingsProps {
  selectedTemplate: Template | null;
}

export const IdentityMappings = ({ selectedTemplate }: IdentityMappingsProps) => {
  if (!selectedTemplate?.identityMappings?.length) return null;
  
  return (
    <div className="mb-6">
      <label className="block mb-3 text-base font-semibold">Identity Mappings</label>
      <div className="space-y-3 bg-gray-50 p-3 rounded-xl">
        {selectedTemplate.identityMappings.map((identity, idx) => (
          <div key={identity.id + '-' + idx} className="flex items-center gap-2 p-2 bg-white border border-gray-100 rounded-lg">
            <div className="flex-1">
              <div className="font-medium text-blue-700">{identity.name}</div>
            </div>
            <div className="text-xs text-blue-500 bg-blue-50 border border-blue-200 rounded-lg px-3 py-2">
              Identity
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}; 