interface MappingCellProps {
  value: string;
  error?: string;
  onChange: (value: string) => void;
  type: "text" | "select";
  options?: { value: string; label: string }[];
  placeholder?: string;
}

export function MappingCell({ value, onChange, type, options, placeholder, error }: MappingCellProps) {
  const hasError = !!error;
  const borderColor = hasError ? "border-red-500" : "border-gray-200";
  const focusBorderColor = hasError ? "focus:border-red-600" : "focus:border-gray-400";
  
  return (
    <div>
      {type === "select" ? (
        <select
          className={`h-7 w-full px-2 py-0 border ${borderColor} rounded-md ${focusBorderColor} focus:ring-1 focus:ring-gray-200 bg-white hover:border-gray-300 transition-colors cursor-pointer text-gray-900 text-xs`}
          value={value}
          onChange={(e) => onChange(e.target.value)}
        >
          {options?.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      ) : (
        <input
          className={`h-7 w-full border ${borderColor} rounded-md ${focusBorderColor} text-center py-0 text-xs`}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
        />
      )}
      {hasError && (
        <div className="text-red-500 text-xs mt-1">
          {error}
        </div>
      )}
    </div>
  );
} 