import { Button } from "@/components/ui/buttons/button";

interface BatchRunsHeaderProps {
  totalCount: number;
  selectedCount: number;
  isLoading: boolean;
  onDelete: () => void;
}

export function BatchRunsHeader({ 
  totalCount, 
  selectedCount, 
  isLoading, 
  onDelete 
}: BatchRunsHeaderProps) {
  return (
    <div className="flex justify-between items-center">
      <h2 className="text-lg font-semibold">
        Batch Runs ({totalCount} records)
      </h2>
      
      <div className="flex gap-2">
        <Button
          variant="destructive"
          size="sm"
          onClick={onDelete}
          disabled={selectedCount === 0 || isLoading}
        >
          {isLoading ? "Deleting..." : `Delete selected (${selectedCount})`}
        </Button>
      </div>
    </div>
  );
} 